contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with one parameter so the property is quantified over inputs
    function run(bool guessIsOwner) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Read the owner before making any state-changing call
        address owner = c.smartfix_owner(); if (__ESBMC_reverted()) return;

        // Make the state-changing call as a top-level statement and record whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe balances after the call
        uint balC = address(c).balance;
        uint balThis = address(this).balance;

        // General invariant: the call reverts exactly when this contract is not the owner;
        // and if it did not revert then C must have been selfdestructed and thus its balance is 0.
        assert((reverted && owner != address(this)) || (!reverted && owner == address(this) && balC == 0));
    }

    receive() external payable {}
}

