// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool guessIsOwner) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        address owner;
        try c.smartfix_owner() returns (address __r) { owner = __r; } catch { return; }
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balC = address(c).balance;
        uint balThis = address(this).balance;
        assertTrue((reverted && owner != address(this)) || (!reverted && owner == address(this) && balC == 0));
    }

    function testFuzz_run(bool guessIsOwner) public {
        _run(guessIsOwner);
    }

    receive() external payable {}
}
